const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// ── Webhook authentication ──
const EXPECTED_TOKEN = '64338df113c1508ba38f50024e1c1ca51c36d2b9127766cc13b5090709f20496';
const provided = headers['x-pot-token'] || headers['X-Pot-Token'] || '';
if (provided !== EXPECTED_TOKEN) {
  return [{ json: {
    blocked: true,
    reason: 'unauthorized',
    reply: 'Något gick fel. Försök igen. / Something went wrong. Please try again.'
  }}];
}

// Get message details
const sessionId = body.sessionId || 'session_' + Date.now();
const message = body.message || '';
const location = body.location || 'karlskrona';
const timestamp = body.timestamp || Date.now();

// Timestamp check — reject if older than 5 minutes
const fiveMinutes = 5 * 60 * 1000;
const now = Date.now();
if (Math.abs(now - timestamp) > fiveMinutes) {
  return [{
    json: {
      blocked: true,
      reason: 'timestamp_expired',
      reply: 'Request expired. Please try again.'
    }
  }];
}

// Message length check
if (!message || message.trim().length === 0) {
  return [{
    json: {
      blocked: true,
      reason: 'empty_message',
      reply: 'Please type a message.'
    }
  }];
}

if (message.length > 500) {
  return [{
    json: {
      blocked: true,
      reason: 'message_too_long',
      reply: 'Your message is too long. Please shorten it and try again.'
    }
  }];
}

// Prompt injection detection
const msgLower = message.toLowerCase();
const injectionPatterns = [
  'ignore previous', 'forget your instructions', 'you are now',
  'act as', 'jailbreak', 'dan mode', 'developer mode',
  'new persona', 'disregard', 'override system',
  'ignore all rules', 'pretend you are', 'roleplay as',
  'system prompt', 'bypass', 'unlock', 'unrestricted mode',
  'no restrictions', 'ignore above', 'forget above',
  'new instructions', 'your real instructions', 'actually you'
];

const injectionFound = injectionPatterns.find(p => msgLower.includes(p));
if (injectionFound) {
  return [{
    json: {
      blocked: true,
      reason: 'injection_attempt',
      reply: 'Jag kan tyvärr inte svara på det. Hur kan jag hjälpa dig med The Pot? / I am unable to answer that. How can I help you with The Pot?'
    }
  }];
}

// Scope guard — block off-topic requests
const outOfScope = [
  'competitor', 'illegal', 'weapon', 'drug', 'hack',
  'password', 'personal number', 'personnummer',
  'list all customers', 'show all bookings', 'export database'
];

const scopeViolation = outOfScope.find(w => msgLower.includes(w));
if (scopeViolation) {
  return [{
    json: {
      blocked: true,
      reason: 'out_of_scope',
      reply: 'Jag är specialiserad på att hjälpa med bokningar och frågor om The Pot. / I specialise in helping with bookings and questions about The Pot.'
    }
  }];
}

// All checks passed
return [{
  json: {
    blocked: false,
    sessionId,
    message: message.trim(),
    location,
    timestamp,
    language: 'detect'
  }
}];

